A debounce function limits how often a function can be called. It ensures the function is only called after a specified delay since the last invocation. This is useful for search inputs, window resizing, and button clicks:

```javascript
function debounce(func, delay) {
    let timeoutId;

    return function(...args) {
        // Clear any pending timeout
        clearTimeout(timeoutId);

        // Set new timeout
        timeoutId = setTimeout(() => {
            func.apply(this, args);
        }, delay);
    };
}

// Usage example: debounce a search input
const searchInput = document.getElementById('search');
const debouncedSearch = debounce(function(event) {
    console.log('Searching for:', event.target.value);
    // API call here
}, 300);

searchInput.addEventListener('input', debouncedSearch);

// Immediate version (leading edge): fires immediately then debounces
function debounceLeading(func, delay) {
    let timeoutId;

    return function(...args) {
        const callNow = !timeoutId;

        clearTimeout(timeoutId);
        timeoutId = setTimeout(() => {
            timeoutId = null;
        }, delay);

        if (callNow) {
            func.apply(this, args);
        }
    };
}

// Throttle vs Debounce:
// - Debounce: delays execution until after a pause
// - Throttle: ensures execution at most once per interval
```

Key points: each call resets the timer. The function only executes after the specified delay since the LAST call. Common delay values: 300ms for search inputs, 150ms for resize handlers.

Here is a Python function that calculates the Fibonacci sequence using memoization:

def fibonacci_memo(n, memo=None):
    if memo is None:
        memo = {}
    if n <= 1:
        return n
    if n in memo:
        return memo[n]
    memo[n] = fibonacci_memo(n-1, memo) + fibonacci_memo(n-2, memo)
    return memo[n]

def fibonacci_iterative(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

# Example
for i in range(10):
    print(f'F({i}) = {fibonacci_memo(i)}')

Memoization reduces time complexity from O(2^n) to O(n). The iterative version uses O(1) space. Python handles arbitrarily large Fibonacci numbers with its built-in big integers.

Custom hooks in React are JavaScript functions that start with 'use' and allow you to encapsulate reusable stateful logic. For data fetching, a custom hook typically manages loading, error, and data states, and triggers side effects. The most common pattern uses `useState` to hold the fetched data and error status, and `useEffect` to perform the actual fetch when the component mounts or when dependencies change. You should handle cleanup to prevent state updates on unmounted components and support aborting stale requests. Here is a robust `useFetch` custom hook example:

```javascript
import { useState, useEffect, useCallback } from 'react';

function useFetch(url, options = {}) {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const fetchData = useCallback(async (abortController) => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(url, {
        ...options,
        signal: abortController.signal
      });
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const result = await response.json();
      setData(result);
    } catch (err) {
      if (err.name !== 'AbortError') {
        setError(err.message);
      }
    } finally {
      setLoading(false);
    }
  }, [url]);

  useEffect(() => {
    const abortController = new AbortController();
    fetchData(abortController);
    return () => abortController.abort();
  }, [fetchData]);

  return { data, loading, error };
}

// Usage in a component:
function UserProfile({ userId }) {
  const { data, loading, error } = useFetch(
    `https://api.example.com/users/${userId}`
  );

  if (loading) return <p>Loading...</p>;
  if (error) return <p>Error: {error}</p>;
  return (
    <div>
      <h1>{data.name}</h1>
      <p>{data.email}</p>
    </div>
  );
}
```

